// Parse the incoming widget payload
const payload = $input.first().json;
const widgets = payload.widgets || [];

// Build email list
const items = widgets.map(function(w) {
  return {
    json: {
      email_to: null,
      company: w.company,
      domain: w.domain,
      embed_code: w.embed,
      status: w.status,
      subject: payload.subject || 'Your ADA Compliance Widget is Ready',
      body_template: payload.body || 'Install this code on your website to display your compliance badge.'
    }
  };
});

// If no specific emails, create single item for preview
if (items.length === 0) {
  items.push({
    json: {
      email_to: null,
      company: 'Preview',
      domain: 'example.com',
      embed_code: '<script src="https://adaswift.com/widget.js?domain=example.com" async></script>',
      status: 'preview',
      subject: payload.subject || 'Your ADA Compliance Widget is Ready',
      body_template: payload.body || 'Install this code on your website to display your compliance badge.'
    }
  });
}

return items;

