const results = $input.all();
const sent = results.filter(function(r) { return !r.json.error; }).length;
const failed = results.filter(function(r) { return r.json.error; }).length;

return [{
  json: {
    status: 'complete',
    total_attempted: results.length,
    sent: sent,
    failed: failed
  }
}];
